{
  "title": "The Gilded Ruin Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Massive iron gates twisted open, ivy-choked stone archways, broken royal crests overhead, dust swirling in the evening light.",
      "characters": ["Elen the Healer", "Kael the Scout", "Maren the Mage"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper warnings in the outer square.",
      "visual_description": "Huddled figures in ragged cloaks, pointing toward the inner city, a child hiding behind a cracked fountain, shadows stretching from collapsed buildings.",
      "characters": ["Elen the Healer", "Town Elder", "Young Mother"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrol marches past a crumbling temple.",
      "visual_description": "Sunlight glinting off dented plate armor, a captain with a torn banner, soldiers scanning rooftops, dust motes in the air.",
      "characters": ["Kael the Scout", "Patrol Captain", "Soldier 1", "Soldier 2"]
    },
    {
      "scene_number": 4,
      "caption": "Kael scouts a side alley to avoid the patrol.",
      "visual_description": "Narrow passage choked with rubble, faded murals on chipped walls, a stray cat darting into shadow, Kael pressing against the stone.",
      "characters": ["Kael the Scout"]
    },
    {
      "scene_number": 5,
      "caption": "Maren detects a magic door hidden behind a tapestry.",
      "visual_description": "Threadbare tapestry of a dragon hunt, faint blue runes pulsing beneath it, Maren's hand glowing as she traces the spell, dust motes dancing.",
      "characters": ["Maren the Mage", "Elen the Healer"]
    },
    {
      "scene_number": 6,
      "caption": "The party opens the magic door and enters a cursed tower.",
      "visual_description": "Iron door grinding open, spiral stairs ascending into darkness, a cold wind carrying whispers, cobwebs shimmering.",
      "characters": ["Elen the Healer", "Kael the Scout", "Maren the Mage"]
    },
    {
      "scene_number": 7,
      "caption": "Inside the tower, illusions of treasure tempt them.",
      "visual_description": "Piles of gold coins that flicker into bones, a jeweled crown hovering above an altar, ghostly hands reaching from the floor.",
      "characters": ["Elen the Healer", "Kael the Scout", "Maren the Mage"]
    },
    {
      "scene_number": 8,
      "caption": "Kael resists a vision of his lost home.",
      "visual_description": "Shimmering image of a warm hearth and a smiling family, Kael's face streaked with tears, Maren pulling him back by the arm.",
      "characters": ["Kael the Scout", "Maren the Mage"]
    },
    {
      "scene_number": 9,
      "scene_number": 9,
      "caption": "They find the captive in a top-floor cage.",
      "visual_description": "Cage of black iron suspended from chains, a figure in rags gripping the bars, weak light from a narrow window casting bars across her face.",
      "characters": ["Elen the Healer", "Kael the Scout", "Maren the Mage", "Princess Lira"]
    },
    {
      "scene_number": 10,
      "caption": "Elen picks the lock while Maren wards the door.",
      "visual_description": "Elen's steady hands working a thin pick into the rusted lock, Maren with palms pressed against the door, blue light sealing the entrance.",
      "characters": ["Elen the Healer", "Maren the Mage", "Princess Lira"]
    },
    {
      "scene_number": 11,
      "caption": "The cage door swings open and Princess Lira steps out.",
      "visual_description": "Rusty hinges groaning, Lira stumbling forward into Elen's arms, her torn dress and bruised wrists visible in the dim light.",
      "characters": ["Elen the Healer", "Princess Lira"]
    },
    {
      "scene_number": 12,
      "caption": "Alarms sound as a patrol discovers the broken door.",
      "visual_description": "Horn blasts echoing through the tower, shouting from below, armored boots pounding on stone stairs, dust shaking from the ceiling.",
      "characters": ["Maren the Mage", "Patrol Captain", "Soldier 1", "Soldier 2"]
    },
    {
      "scene_number": 13,
      "caption": "The party flees down a secret spiral staircase.",
      "visual_description": "Narrow stone steps twisting downward, a single torch flickering, cobwebs brushing their faces, distant shouts behind them.",
      "characters": ["Elen the Healer", "Kael the Scout", "Maren the Mage", "Princess Lira"]
    },
    {
      "scene_number": 14,
      "caption": "They emerge into a courtyard with old royal banners.",
      "visual_description": "Faded gold-and-crimson banners hanging limp from broken poles, a cracked statue of a king, moonlight pooling on flagstones.",
      "characters": ["Elen the Healer", "Kael the Scout", "Maren the Mage", "Princess Lira"]
    },
    {
      "scene_number": 15,
      "caption": "A dragon's shadow passes overhead, but it does not attack.",
      "visual_description": "Giant wings blocking the moon, scales glinting darkly, a low rumble that shakes the ground, then the beast flies onward toward the towers.",
      "characters": ["Elen the Healer", "Kael the Scout", "Maren the Mage", "Princess Lira"]
    },
    {
      "scene_number": 16,
      "caption": "They race toward the bridge as the city crumbles.",
      "visual_description": "Collapsing archways behind them, dust clouds billowing, the stone bridge ahead spanning a dark chasm, lanterns lit along its rails.",
      "characters": ["Elen the Healer", "Kael the Scout", "Maren the Mage", "Princess Lira"]
    },
    {
      "scene_number": 17,
      "caption": "The party crosses the bridge as patrols close in.",
      "visual_description": "Arrows clattering against stone, a burning cart blocking the patrol's path, the party running low over the bridge's worn planks.",
      "characters": ["Elen the Healer", "Kael the Scout", "Maren the Mage", "Princess Lira"]
    },
    {
      "scene_number": 18,
      "caption": "They reach the far side and watch the city burn.",
      "visual_description": "The ruined skyline silhouetted against flames, smoke rising into the night, the party catching their breath on a grassy hill, Princess Lira looking back with tears in her eyes.",
      "characters": ["Elen the Healer", "Kael the Scout", "Maren the Mage", "Princess Lira"]
    }
  ]
}

